style.css:
/* ♡ Sweet Pink Discord Theme ♡ */

/* Main backgrounds */
body,
[class*="appMount"],
[class*="app"] {
    background-color: #ffd1ef !important;
}

/* Panels, sidebars, and chat areas */
[class*="sidebar"],
[class*="chat"],
[class*="members"],
[class*="container"],
[class*="layer"] {
    background-color: #ffd1ef !important;
}

/* Text */
body,
p,
span,
[class*="text"],
[class*="username"],
[class*="title"] {
    color: #ff84d5 !important;
}

/* Message boxes */
textarea,
input {
    background-color: #ffd1ef !important;
    color: #ff84d5 !important;
    border-color: #ff84d5 !important;
}

/* Scrollbars */
::-webkit-scrollbar-thumb {
    background-color: #ff84d5 !important;
}

::-webkit-scrollbar-track {
    background-color: #ffd1ef !important;
}
